3	// of a species relaxing against an identical species must be identical to its
4	// own primitive moments: the density is unchanged, and the cross drift speed
5	// and thermal speed equal the (common) input values.  Uses spatially-constant
6	// fields so the expected DG coefficients are exact.
7	#include <acutest.h>
