30	
31	  double lower[GKYL_MAX_DIM], upper[GKYL_MAX_DIM];
32	  int cells[GKYL_MAX_DIM];
33	  for (int d=0; d<cdim; d++) { lower[d] = -0.5; upper[d] = 0.5; cells[d] = 2; }
34	  for (int d=0; d<vdim; d++) {
35	    lower[cdim+d] = (d==0)? -6.0 : 0.0;
36	    upper[cdim+d] = (d==0)?  6.0 : 6.0;
37	    cells[cdim+d] = 8;
38	  }
39	
40	  double confLower[GKYL_MAX_CDIM], confUpper[GKYL_MAX_CDIM];
41	  int confCells[GKYL_MAX_CDIM];
42	  for (int d=0; d<cdim; d++) {
43	    confLower[d] = lower[d]; confUpper[d] = upper[d]; confCells[d] = cells[d];
