46	  struct gkyl_rect_grid grid, confGrid;
47	  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);
48	  gkyl_rect_grid_init(&confGrid, cdim, confLower, confUpper, confCells);
49	
50	  struct gkyl_basis basis, confBasis;
51	  if (poly_order == 1)
52	    gkyl_cart_modal_gkhybrid(&basis, cdim, vdim);
53	  else
54	    gkyl_cart_modal_serendip(&basis, ndim, poly_order);
55	  gkyl_cart_modal_serendip(&confBasis, cdim, poly_order);
56	
57	  int confGhost[GKYL_MAX_CDIM];
58	  for (int d=0; d<cdim; d++) confGhost[d] = 1;
59	  struct gkyl_range confLocal, confLocal_ext;
60	  gkyl_create_grid_ranges(&confGrid, confGhost, &confLocal_ext, &confLocal);
61	
62	  int nb = confBasis.num_basis;
63	  double fac = pow(sqrt(2.0), cdim); // 0th coeff scale of a constant
64	
65	  // prim_moms layout: [den | upar | vtsq], each nb coefficients.
66	  struct gkyl_array *prim_moms = mkarr(3*nb, confLocal_ext.volume);
67	  gkyl_array_clear(prim_moms, 0.0);
68	  struct gkyl_range_iter iter;
69	  gkyl_range_iter_init(&iter, &confLocal_ext);
70	  while (gkyl_range_iter_next(&iter)) {
71	    long lidx = gkyl_range_idx(&confLocal_ext, iter.idx);
72	    double *d = gkyl_array_fetch(prim_moms, lidx);
73	    d[0*nb + 0] = n0*fac;
74	    d[1*nb + 0] = upar0*fac;
75	    d[2*nb + 0] = vtsq0*fac;
76	  }
77	
78	  double mass = 1.5;
79	  double delta_sr = 1.0, betap1 = 1.0;
