1	#include <acutest.h>
2	#include <gkyl_array.h>
3	#include <gkyl_array_ops.h>
4	#include <gkyl_array_rio.h>
5	#include <gkyl_dg_bin_ops.h>
6	#include <gkyl_mom_calc.h>
7	#include <gkyl_gyrokinetic_cross_prim_moms_bgk.h>
8	#include <gkyl_mom_gyrokinetic.h>
9	#include <gkyl_proj_on_basis.h>
10	#include <gkyl_range.h>
11	#include <gkyl_rect_decomp.h>
12	#include <gkyl_rect_grid.h>
13	#include <gkyl_util.h>
14	#include <math.h>
15	#include <stdio.h>
16	
17	// Allocate cu_dev array
18	static struct gkyl_array*
19	mkarr(long nc, long size, bool use_gpu)
20	{
21	  struct gkyl_array* a = use_gpu? gkyl_array_cu_dev_new(GKYL_DOUBLE, nc, size) : gkyl_array_new(GKYL_DOUBLE, nc, size);
22	  return a;
23	}
24	
25	// Create ghost ranges
26	struct skin_ghost_ranges
27	{
28	  struct gkyl_range lower_skin[GKYL_MAX_DIM];
29	  struct gkyl_range lower_ghost[GKYL_MAX_DIM];
30	
31	  struct gkyl_range upper_skin[GKYL_MAX_DIM];
32	  struct gkyl_range upper_ghost[GKYL_MAX_DIM];
33	};
34	
35	// Create ghost and skin sub-ranges given a parent range
36	static void
37	skin_ghost_ranges_init(struct skin_ghost_ranges *sgr,
38	                       const struct gkyl_range *parent, const int *ghost)
39	{
40	  int ndim = parent->ndim;
41	
42	  for (int d = 0; d < ndim; ++d){
43	    gkyl_skin_ghost_ranges(&sgr->lower_skin[d], &sgr->lower_ghost[d],
44	                           d, GKYL_LOWER_EDGE, parent, ghost);
45	    gkyl_skin_ghost_ranges(&sgr->upper_skin[d], &sgr->upper_ghost[d],
46	                           d, GKYL_UPPER_EDGE, parent, ghost);
47	  }
48	}
49	
50	void eval_den_e(double t, const double *xn, double *restrict fout, void *ctx)
51	{
52	  double x = xn[0];
53	  fout[0] = 1.0e19;
54	}
55	void eval_den_i(double t, const double *xn, double *restrict fout, void *ctx)
56	{
57	  double x = xn[0];
58	  fout[0] = 1.0e19;
59	}
60	void eval_vtsq_e(double t, const double *xn, double* restrict fout, void *ctx)
61	{
62	  double x = xn[0];
63	  double eV = 1.602e-19;
64	  double me = 9.11e-31;
65	  double Te = 30.0*eV;
66	  fout[0] = Te/me;
67	}
68	void eval_vtsq_i(double t, const double *xn, double* restrict fout, void *ctx)
69	{
70	  double x = xn[0];
71	  double eV = 1.602e-19;
72	  double mi = 1.67e-27;
73	  double Ti = 10.0*eV;
74	  fout[0] = Ti/mi;
75	}
76	void eval_upar_e(double t, const double *xn, double *restrict fout, void *ctx)
77	{
78	  double x = xn[0];
79	  double vtsq[1];
80	  eval_vtsq_e(t, xn, vtsq, ctx);
81	  double vt = sqrt(vtsq[0]); 
82	  fout[0] = 0.01*vt;
83	}
84	void eval_upar_i(double t, const double *xn, double *restrict fout, void *ctx)
85	{
86	  double x = xn[0];
87	  double vtsq[1];
88	  eval_vtsq_i(t, xn, vtsq, ctx);
89	  double vt = sqrt(vtsq[0]); 
90	  fout[0] = 0.01*vt;
91	}
92	void eval_nu_ei(double t, const double *xn, double *restrict fout, void *ctx)
93	{
94	  double x = xn[0];
95	  double eV = 1.602e-19;
96	  double me = 9.11e-31;
97	  double Te = 30.0*eV;
98	  double logLambdaElc, nuElc;
99	  double den[1];
100	  eval_den_e(t, xn, den, ctx); 
101	  logLambdaElc = 6.6 - 0.5*log(den[0]/1.0e20) + 1.5*log(Te/eV);
102	  nuElc = logLambdaElc*pow(eV,4)*den[0]/(6.0*sqrt(2.0)*pow(M_PI,3.0/2.0)*pow(8.85e-12,2)*sqrt(me)*pow(Te,3.0/2.0));
103	  fout[0] = nuElc/1.96;
104	}
105	void eval_nu_ie(double t, const double *xn, double *restrict fout, void *ctx)
106	{
107	  double x = xn[0];
108	  double me = 9.11e-31;
109	  double mi = 1.67e-27;
110	  double nu_ei[1];
111	  eval_nu_ei(t, xn, nu_ei, ctx);  
112	  fout[0] = nu_ei[0]*me/mi;
113	}
114	
115	void test_1x1v(int poly_order, bool use_gpu)
116	{
117	  double eV = 1.602e-19;
118	  double me = 9.11e-31;
119	  double mi = 1.67e-27;
120	  double Te = 30.0*eV;
121	  double delta_sr = 1.0;
122	  double betaGreenep1 = 1.0;
123	  double vt = sqrt(Te/me);
124	
125	  double lower[] = {-0.5, -5.0*vt}, upper[] = {0.5, 5.0*vt};
126	  int cells[] = {2, 32};
127	  int vdim = 1, cdim = 1;
128	  int ndim = cdim + vdim;
129	
130	  double confLower[] = {lower[0]}, confUpper[] = {upper[0]};
131	  int confCells[] = {cells[0]};
132	
133	  // Grids
134	  struct gkyl_rect_grid grid;
135	  gkyl_rect_grid_init(&grid, ndim, lower, upper, cells);
136	  struct gkyl_rect_grid confGrid;
137	  gkyl_rect_grid_init(&confGrid, cdim, confLower, confUpper, confCells);
138	
139	  // Basis functions
140	  struct gkyl_basis basis, confBasis;
141	  if (poly_order==1)
142	    gkyl_cart_modal_gkhybrid(&basis, cdim, vdim);
143	  else
144	    gkyl_cart_modal_serendip(&basis, ndim, poly_order);
145	  gkyl_cart_modal_serendip(&confBasis, cdim, poly_order);
146	
147	  // Configuration space range
148	  int confGhost[] = {1};
149	  struct gkyl_range confLocal, confLocal_ext;
150	  gkyl_create_grid_ranges(&confGrid, confGhost, &confLocal_ext, &confLocal);
151	  struct skin_ghost_ranges confSkin_ghost;
152	  skin_ghost_ranges_init(&confSkin_ghost, &confLocal_ext, confGhost);
153	
154	  // Phase space range
155	  int ghost[] = {confGhost[0], 0};
156	  struct gkyl_range local, local_ext;
157	  gkyl_create_grid_ranges(&grid, ghost, &local_ext, &local);
158	  struct skin_ghost_ranges skin_ghost;
159	  skin_ghost_ranges_init(&skin_ghost, &local_ext, ghost);
160	
161	  // Create moment arrays
162	  // (1) electron
163	  struct gkyl_array *den_e_ho, *upar_e_ho, *vtsq_e_ho;
164	  den_e_ho = mkarr(confBasis.num_basis, confLocal_ext.volume, false);
165	  upar_e_ho = mkarr(confBasis.num_basis, confLocal_ext.volume, false);
166	  vtsq_e_ho = mkarr(confBasis.num_basis, confLocal_ext.volume, false);
167	  gkyl_proj_on_basis *proj_den_e = gkyl_proj_on_basis_new(&confGrid, &confBasis, poly_order+1, 1, eval_den_e, NULL);
168	  gkyl_proj_on_basis *proj_upar_e = gkyl_proj_on_basis_new(&confGrid, &confBasis, poly_order+1, 1, eval_upar_e, NULL);
169	  gkyl_proj_on_basis *proj_vtsq_e = gkyl_proj_on_basis_new(&confGrid, &confBasis, poly_order+1, 1, eval_vtsq_e, NULL);
170	  gkyl_proj_on_basis_advance(proj_den_e, 0.0, &confLocal, den_e_ho);
171	  gkyl_proj_on_basis_advance(proj_upar_e, 0.0, &confLocal, upar_e_ho);
172	  gkyl_proj_on_basis_advance(proj_vtsq_e, 0.0, &confLocal, vtsq_e_ho);
173	  struct gkyl_array *den_e, *upar_e, *vtsq_e;
174	  if (use_gpu) {
175	    den_e = mkarr(confBasis.num_basis, confLocal_ext.volume, use_gpu);
176	    upar_e = mkarr(confBasis.num_basis, confLocal_ext.volume, use_gpu);
177	    vtsq_e = mkarr(confBasis.num_basis, confLocal_ext.volume, use_gpu);
178	    gkyl_array_copy(den_e, den_e_ho);
179	    gkyl_array_copy(upar_e, upar_e_ho);
180	    gkyl_array_copy(vtsq_e, vtsq_e_ho);
181	  } else {
182	    den_e = den_e_ho;
183	    upar_e = upar_e_ho;
184	    vtsq_e = vtsq_e_ho;
185	  }
186	  struct gkyl_array *prim_moms_e = mkarr(3*confBasis.num_basis, confLocal_ext.volume, use_gpu);
187	  gkyl_array_set_offset(prim_moms_e, 1., den_e, 0*confBasis.num_basis);
188	  gkyl_array_set_offset(prim_moms_e, 1., upar_e, 1*confBasis.num_basis);
189	  gkyl_array_set_offset(prim_moms_e, 1., vtsq_e, 2*confBasis.num_basis);
190	  // (2) ion
191	  struct gkyl_array *den_i_ho, *upar_i_ho, *vtsq_i_ho;
192	  den_i_ho = mkarr(confBasis.num_basis, confLocal_ext.volume, false);
193	  upar_i_ho = mkarr(confBasis.num_basis, confLocal_ext.volume, false);
194	  vtsq_i_ho = mkarr(confBasis.num_basis, confLocal_ext.volume, false);
195	  gkyl_proj_on_basis *proj_den_i = gkyl_proj_on_basis_new(&confGrid, &confBasis, poly_order+1, 1, eval_den_i, NULL);
196	  gkyl_proj_on_basis *proj_upar_i = gkyl_proj_on_basis_new(&confGrid, &confBasis, poly_order+1, 1, eval_upar_i, NULL);
197	  gkyl_proj_on_basis *proj_vtsq_i = gkyl_proj_on_basis_new(&confGrid, &confBasis, poly_order+1, 1, eval_vtsq_i, NULL);
198	  gkyl_proj_on_basis_advance(proj_den_i, 0.0, &confLocal, den_i_ho);
199	  gkyl_proj_on_basis_advance(proj_upar_i, 0.0, &confLocal, upar_i_ho);
200	  gkyl_proj_on_basis_advance(proj_vtsq_i, 0.0, &confLocal, vtsq_i_ho);
201	  struct gkyl_array *den_i, *upar_i, *vtsq_i;
202	  if (use_gpu) {
203	    den_i = mkarr(confBasis.num_basis, confLocal_ext.volume, use_gpu);
204	    upar_i = mkarr(confBasis.num_basis, confLocal_ext.volume, use_gpu);
205	    vtsq_i = mkarr(confBasis.num_basis, confLocal_ext.volume, use_gpu);
206	    gkyl_array_copy(den_i, den_i_ho);
207	    gkyl_array_copy(upar_i, upar_i_ho);
208	    gkyl_array_copy(vtsq_i, vtsq_i_ho);
209	  } else {
210	    den_i = den_i_ho;
211	    upar_i = upar_i_ho;
212	    vtsq_i = vtsq_i_ho;
213	  }
214	  struct gkyl_array *prim_moms_i = mkarr(3*confBasis.num_basis, confLocal_ext.volume, use_gpu);
215	  gkyl_array_set_offset(prim_moms_i, 1., den_i, 0*confBasis.num_basis);
