227	  // Calculate the cross primitive moments
228	  gkyl_gyrokinetic_cross_prim_moms_bgk *crossPrimMomsCalc = gkyl_gyrokinetic_cross_prim_moms_bgk_new(&basis, &confBasis, use_gpu);
229	  struct gkyl_array *prim_moms_cross_e = mkarr(3*confBasis.num_basis, confLocal_ext.volume, use_gpu);
230	  struct gkyl_array *prim_moms_cross_i = mkarr(3*confBasis.num_basis, confLocal_ext.volume, use_gpu);
231	  gkyl_gyrokinetic_cross_prim_moms_bgk_advance(crossPrimMomsCalc, &confLocal, delta_sr, betaGreenep1,
232	     me, prim_moms_e, mi, prim_moms_i, prim_moms_cross_e);
233	  gkyl_gyrokinetic_cross_prim_moms_bgk_advance(crossPrimMomsCalc, &confLocal, delta_sr, betaGreenep1,
234	     mi, prim_moms_i, me, prim_moms_e, prim_moms_cross_i);
235	  gkyl_gyrokinetic_cross_prim_moms_bgk_release(crossPrimMomsCalc);
236	
237	  // Write out on host
238	  //char fname[1024];
239	  //sprintf(fname, "ctest_gyrokinetic_cross_prim_moms_bgk_%dx%dv_p%d.gkyl", cdim, vdim, poly_order);
240	  //gkyl_grid_sub_array_write(&confGrid, &confLocal, 0, prim_moms_cross, fname);
241	
242	  // Compare with the expected cross moments
243	  for (int k=0; k<cells[0]; k++) {
244	    int idx[] = {k+1};
245	    long linidx = gkyl_range_idx(&confLocal, idx);
246	    const double *primMomsCross_e = gkyl_array_cfetch(prim_moms_cross_e, linidx);
247	    const double *primMomsCross_i = gkyl_array_cfetch(prim_moms_cross_i, linidx);
248	    TEST_CHECK( gkyl_compare(1.0e19, primMomsCross_e[0*confBasis.num_basis]/sqrt(2), 1e-12*1.0e19) );
249	    TEST_CHECK( gkyl_compare(1.16391130e4, primMomsCross_e[1*confBasis.num_basis]/sqrt(2), 1e-12*1.16391130e4) );
250	    TEST_CHECK( gkyl_compare(5.27398867e12, primMomsCross_e[2*confBasis.num_basis]/sqrt(2), 1e-12*5.27398867e12) );
251	    TEST_CHECK( gkyl_compare(1.0e19, primMomsCross_i[0*confBasis.num_basis]/sqrt(2), 1e-12*1.0e19) );
252	    TEST_CHECK( gkyl_compare(1.16391130e4, primMomsCross_i[1*confBasis.num_basis]/sqrt(2), 1e-12*1.16391130e4) );
253	    TEST_CHECK( gkyl_compare(2.74816328e9, primMomsCross_i[2*confBasis.num_basis]/sqrt(2), 1e-12*2.74816328e9) );
254	    TEST_MSG("Produced: %.13e, \t%.13e, \t%.13e", primMomsCross_e[0*confBasis.num_basis]/sqrt(2), primMomsCross_e[1*confBasis.num_basis]/sqrt(2), primMomsCross_e[2*confBasis.num_basis]/sqrt(2));
255	  } // The hard coded numbers are expected values. The basis is looked up in maxima with: load("basis-precalc/basisSer1x"); polyOrder:1$ basis:basisC[polyOrder];
256	
257	  // Release memory for moment data object
258	  gkyl_array_release(den_e_ho);
259	  gkyl_array_release(upar_e_ho);
260	  gkyl_array_release(vtsq_e_ho);
261	  gkyl_array_release(den_i_ho);
262	  gkyl_array_release(upar_i_ho);
263	  gkyl_array_release(vtsq_i_ho);
264	  if (use_gpu) {
