  //char fname[1024];
  //sprintf(fname, "ctest_gyrokinetic_cross_prim_moms_bgk_%dx%dv_p%d.gkyl", cdim, vdim, poly_order);
  //gkyl_grid_sub_array_write(&confGrid, &confLocal, 0, prim_moms_cross, fname);

